/*
 * QemuHDAGainTable.h
 * Software volume curve: index 0 = silence, index N (1..64) =
 * (N - 64) * 0.75 dB, i.e. -47.25 dB .. 0 dB. Matches the dB range given
 * to the IOAudioLevelControl (-48 dB .. 0 dB over 0 .. 64), so the value
 * CoreAudio displays is the gain we actually apply.
 *
 * Precomputed so the kernel never needs pow()/log() at runtime.
 * Generated by: python3 -c "[10**((v-64)*0.75/20) for v in range(1,65)]"
 *
 * SPDX-License-Identifier: MIT
 */

